const f = $input.first().json;
const codigo = String(f.codigo ?? '').trim().toUpperCase();
if (!/^PRP-\d{4}-\d{4}$/.test(codigo)) throw new Error('Plano de expedição: código de proposta inválido ("' + codigo.slice(0, 30) + '"). Use a ligação do email.');
const nome = String(f['O seu nome'] ?? '').trim().slice(0, 80);
if (nome.length < 2) throw new Error('Plano de expedição ' + codigo + ': indique o seu nome.');
const reservaTxt = String(f['Os dados da reserva estão corretos?'] ?? '');
if (!['Sim', 'Não'].includes(reservaTxt)) throw new Error('Plano de expedição ' + codigo + ': indique se os dados da reserva estão corretos.');
const notas = String(f['Notas'] ?? '').trim().slice(0, 1000);
if (reservaTxt === 'Não') return [{ json: { codigo, reserva_ok: false, notas, planeada_por: nome } }];
const dias = Number(f['Tempo de produção (dias)']);
if (!Number.isInteger(dias) || dias < 0 || dias > 365) throw new Error('Plano de expedição ' + codigo + ': tempo de produção inválido (0 a 365 dias).');
const stockTxt = String(f['Stock disponível'] ?? '');
if (!['Sim', 'Não'].includes(stockTxt)) throw new Error('Plano de expedição ' + codigo + ': indique se há stock.');
const data = String(f['Data de recolha'] ?? '').slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(data) || isNaN(new Date(data + 'T00:00:00Z').getTime())) throw new Error('Plano de expedição ' + codigo + ': data de recolha inválida.');
const hoje = new Date().toISOString().slice(0, 10);
if (data < hoje) throw new Error('Plano de expedição ' + codigo + ': a data de recolha (' + data + ') já passou.');
return [{ json: { codigo, reserva_ok: true, tempo_producao_dias: dias, stock_ok: stockTxt === 'Sim', data_recolha: data, notas, planeada_por: nome } }];

const plano = $('Validar plano').first().json;
const p = $input.first().json;
if (!p || !p.id) throw new Error('Plano de expedição: proposta ' + plano.codigo + ' não encontrada.');
if (!['aceite', 'em_expedicao'].includes(p.estado)) throw new Error('Plano de expedição: a proposta ' + p.codigo + ' está no estado ' + p.estado + '; só se planeia a expedição de propostas confirmadas pelo cliente (aceite) e ainda sem follow-up.');
return [{ json: { ...plano, proposta_id: p.id, cliente: p.cliente, frete_escolhido_id: p.frete_escolhido_id ?? null } }];

const r = $input.first().json;
const plano = $('Verificar proposta').first().json;
if (!r || !r.id) throw new Error('Plano de expedição: não existe linha de expedição para ' + plano.codigo + ' (confirmação em falta?). Nada foi gravado.');
return [{ json: { codigo: plano.codigo } }];

const plano = $('Verificar proposta').first().json;
const c = $('Ler cotação escolhida').first().json || {};
const t = $('Ler transportadora da reserva').first().json || {};
const MADALENA = 'REDACTED@example.invalid';
const BARBARA = 'REDACTED@example.invalid';
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (d) => { const x = new Date(String(d).slice(0, 10) + 'T00:00:00Z'); return String(x.getUTCDate()).padStart(2, '0') + '/' + String(x.getUTCMonth() + 1).padStart(2, '0') + '/' + x.getUTCFullYear(); };
const codigo = plano.codigo;
if (!plano.reserva_ok) {
  const info = c.id ? ' (' + esc(t.nome || 'transportadora') + ', ' + esc(c.modo || '-') + (c.ref_transportadora ? ', ref. ' + esc(c.ref_transportadora) : '') + ')' : '';
  const corpo = '<p>A ' + esc(plano.planeada_por) + ' indicou que os dados da reserva do frete da proposta <b>' + esc(codigo) + '</b>' + info + ' <b>não estão corretos</b>. O plano de expedição não foi gravado e a proposta continua aceite.</p>' + (plano.notas ? '<p>Nota: ' + esc(plano.notas) + '</p>' : '') + '<p>Para corrigir: no <a href="https://mmacedo87.app.n8n.cloud/form/confirmar-reserva">formulário de confirmação de reserva</a>, cancele a reserva atual e confirme a transportadora certa. A Madalena recebe de novo o link do plano.</p><p>Cumprimentos,<br>Sistema de propostas (mensagem automática)</p>';
  return [{ json: { seguir: false, codigo, assunto: '[' + codigo + '] Reserva de frete a corrigir antes do plano de expedição', corpo_html: corpo, para: BARBARA, cc: MADALENA, slack_texto: '⚠️ Plano da *' + codigo + '* não gravado: ' + plano.planeada_por + ' indicou que a reserva do frete está errada. Corrigir no WF13.' } }];
}
if (!c.id || c.estado_reserva !== 'confirmada') throw new Error('Plano de expedição ' + codigo + ': a reserva do frete ainda não está confirmada. Confirme-a no formulário de confirmação de reserva e use o link que recebe por email.');
if (!['rodoviario', 'maritimo', 'aereo', 'ferroviario'].includes(c.modo)) throw new Error('Plano de expedição ' + codigo + ': a cotação escolhida não tem um modo de expedição válido.');
if (!t.id) throw new Error('Plano de expedição ' + codigo + ': não encontrei a transportadora da reserva.');
const chegadaDt = c.transito_dias != null ? new Date(plano.data_recolha + 'T00:00:00Z') : null;
if (chegadaDt) chegadaDt.setUTCDate(chegadaDt.getUTCDate() + Number(c.transito_dias));
const chegada = chegadaDt ? chegadaDt.toISOString().slice(0, 10) : null;
const avisoValidade = !!c.validade && plano.data_recolha > String(c.validade).slice(0, 10);
const slack = '📦 Plano de expedição de *' + codigo + '* guardado · ' + t.nome + ' · ' + c.modo + ' · recolha ' + fmt(plano.data_recolha) + (chegada ? ' · chegada estimada ' + fmt(chegada) : '') + (avisoValidade ? ' · ⚠️ a recolha é depois da validade da cotação (' + fmt(c.validade) + '): confirmar o preço com a transportadora' : '');
return [{ json: { seguir: true, codigo, proposta_id: plano.proposta_id, tempo_producao_dias: plano.tempo_producao_dias, stock_ok: plano.stock_ok, data_recolha: plano.data_recolha, modo: c.modo, transportadora: t.nome, ref_transportadora: c.ref_transportadora ?? null, notas: plano.notas, planeada_por: plano.planeada_por, chegada_estimada: chegada, aviso_validade: avisoValidade, slack_texto: slack } }];
